import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { Activity, Archive, Ban, Boxes, CheckCircle2, CircleDollarSign, CloudCog, Eye, KeyRound, Link2, Loader2, Megaphone, PauseCircle, PlayCircle, Plus, RefreshCw, Save, Search, ShieldCheck, SlidersHorizontal, Sparkles, TestTube2, Ticket, Users, X } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";
import { MiniOmniRouteWizard } from "./MiniOmniRouteWizard";
import { KiwiAutoPolicyPanel } from "./KiwiAutoPolicyPanel";
import { ModelIdentityRegistry } from "./ModelIdentityRegistry";

type Section = "operations" | "providers" | "models" | "access" | "growth";
type Provider = { id: number; slug: string; displayName: string; baseUrl: string; isEnabled: boolean; isHealthy: boolean; isConfigured: boolean };
type Model = { id: number; slug: string; displayName: string; upstreamId: string; providerId: number; contextWindow: number; creditCostPer1kTokens: string; isEnabled: boolean; routingConfig?: { protocol?: string; priority?: number; fallbackProviderId?: number; capabilities?: Record<string, boolean> } };
type ModelRow = { model: Model; provider: { displayName: string } };

const asArray = <T,>(value: unknown) => Array.isArray(value) ? value as T[] : [];
const number = (value: unknown) => Number.isFinite(Number(value)) ? Number(value) : 0;
const compact = (value: unknown) => new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 }).format(number(value));
const confirmAction = (message: string) => window.confirm(message);

function Panel({ title, detail, action, children }: { title: string; detail?: string; action?: React.ReactNode; children: React.ReactNode }) {
  return <section className="rounded-2xl border border-white/8 bg-[#101112] p-5 shadow-[0_12px_40px_rgba(0,0,0,.12)]"><div className="mb-4 flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-medium text-zinc-100">{title}</h2>{detail && <p className="mt-1 max-w-2xl text-xs leading-5 text-zinc-500">{detail}</p>}</div>{action}</div>{children}</section>;
}
function Empty({ children }: { children: React.ReactNode }) { return <p className="rounded-xl border border-dashed border-white/10 bg-black/15 p-4 text-sm text-zinc-500">{children}</p>; }

function AdminUserIntelligence() {
  const [search, setSearch] = useState("");
  const [selectedUserId, setSelectedUserId] = useState(0);
  const [creditDelta, setCreditDelta] = useState(0);
  const [creditBucket, setCreditBucket] = useState<"stipend" | "purchased">("purchased");
  const [creditDescription, setCreditDescription] = useState("Founder ledger correction");
  const users = trpc.admin.users.useQuery({ search: search || undefined, status: "all", limit: 100, offset: 0 });
  const sessions = trpc.admin.userSessions.useQuery({ userId: selectedUserId }, { enabled: selectedUserId > 0 });
  const usage = trpc.admin.userUsage.useQuery({ userId: selectedUserId }, { enabled: selectedUserId > 0 });
  const ledger = trpc.admin.userLedger.useQuery({ userId: selectedUserId }, { enabled: selectedUserId > 0 });
  const revoke = trpc.admin.revokeUserSessions.useMutation({ onSuccess: () => { void sessions.refetch(); toast.success("User sessions revoked"); }, onError: error => toast.error(error.message) });
  const revokeKeys = trpc.admin.revokeUserApiKeys.useMutation({ onSuccess: result => toast.success(`${result.count} API keys revoked`), onError: error => toast.error(error.message) });
  const rotateKeys = trpc.admin.rotateUserApiKeys.useMutation({ onSuccess: result => { toast.success(`Keys rotated. Replacement: ${result.replacement.plainKey}`); void users.refetch(); }, onError: error => toast.error(error.message) });
  const expireKeys = trpc.admin.expireUserApiKeys.useMutation({ onSuccess: result => toast.success(`${result.count} API keys expired`), onError: error => toast.error(error.message) });
  const quarantineKeys = trpc.admin.quarantineUserApiKeys.useMutation({ onSuccess: result => toast.success(`${result.count} API keys quarantined`), onError: error => toast.error(error.message) });
  const adjustCredit = trpc.admin.adjustUserCredits.useMutation({ onSuccess: () => { void ledger.refetch(); void users.refetch(); setCreditDelta(0); toast.success("Credit ledger adjusted"); }, onError: error => toast.error(error.message) });
  const rows = asArray<{ id: number; name: string; email: string; role: string; isDisabled: boolean; emailVerifiedAt: string | null; activeKeys: number; activeSessions: number; requests24h: number; purchasedCredits: string; stipendCredits: string }>(users.data);
  const sessionRows = asArray<{ id: string; expiresAt: string; createdAt: string }>(sessions.data);
  const usageRows = asArray<{ modelSlug: string; status: string; requests: number; inputTokens: number; outputTokens: number; avgLatencyMs: number; lastRequestAt: string }>(usage.data);
  const ledgerRows = asArray<{ id: string; amount: string; entryType: string; description: string; createdAt: string }>(ledger.data).slice(0, 8);
  return <Panel title="User intelligence & incident response" detail="Search accounts, inspect verification and risk signals, review sessions, drill into route usage, and inspect the immutable credit ledger."><div className="grid gap-3 lg:grid-cols-[1fr_1.4fr]"><div><div className="relative"><Search className="pointer-events-none absolute left-3 top-3.5 size-4 text-zinc-600" /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search name or email" className="bg-black/25 pl-9" /></div><div className="mt-3 max-h-96 space-y-2 overflow-auto">{rows.length ? rows.map(row => <button key={row.id} type="button" onClick={() => setSelectedUserId(row.id)} className={`w-full rounded-xl border p-3 text-left transition ${selectedUserId === row.id ? "border-[#8ee53f]/50 bg-[#8ee53f]/5" : "border-white/7 bg-black/15 hover:border-white/15"}`}><div className="flex items-start justify-between gap-2"><div><p className="text-sm text-zinc-100">{row.name}</p><p className="mt-1 text-xs text-zinc-500">{row.email}</p></div><span className={`text-[10px] uppercase ${row.isDisabled ? "text-rose-300" : row.emailVerifiedAt ? "text-[#b5ff77]" : "text-amber-200"}`}>{row.isDisabled ? "disabled" : row.emailVerifiedAt ? "verified" : "unverified"}</span></div><p className="mt-2 text-[11px] text-zinc-600">{row.activeKeys} keys · {row.activeSessions} sessions · {row.requests24h} requests/24h · {compact(Number(row.purchasedCredits) + Number(row.stipendCredits))} credits</p></button>) : <Empty>No matching users.</Empty>}</div></div><div className="space-y-3">{selectedUserId ? <><div className="grid gap-2 sm:grid-cols-3"><div className="rounded-xl border border-white/7 bg-black/15 p-3"><p className="text-[10px] uppercase text-zinc-600">Sessions</p><p className="mt-1 text-xl text-zinc-100">{sessionRows.length}</p></div><div className="rounded-xl border border-white/7 bg-black/15 p-3"><p className="text-[10px] uppercase text-zinc-600">Usage groups</p><p className="mt-1 text-xl text-zinc-100">{usageRows.length}</p></div><div className="rounded-xl border border-white/7 bg-black/15 p-3"><p className="text-[10px] uppercase text-zinc-600">Ledger entries</p><p className="mt-1 text-xl text-zinc-100">{ledgerRows.length}</p></div></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" disabled={!sessionRows.length || revoke.isPending} onClick={() => { if (confirmAction("Revoke every active session for this user?")) revoke.mutate({ userId: selectedUserId }); }}><ShieldCheck className="mr-1.5 size-3.5" />Revoke sessions</Button><Button size="sm" variant="outline" className="text-rose-300" disabled={revokeKeys.isPending} onClick={() => { if (confirmAction("Revoke every active API key for this user? This cannot be undone.")) revokeKeys.mutate({ userId: selectedUserId }); }}>Revoke API keys</Button><Button size="sm" variant="outline" disabled={rotateKeys.isPending} onClick={() => { if (confirmAction("Rotate this user’s keys and reveal one replacement once?")) rotateKeys.mutate({ userId: selectedUserId }); }}>Rotate keys</Button><Button size="sm" variant="ghost" className="text-amber-200" disabled={expireKeys.isPending} onClick={() => { if (confirmAction("Expire every active API key for this user? Expired keys cannot authenticate.")) expireKeys.mutate({ userId: selectedUserId }); }}>Expire keys</Button><Button size="sm" variant="ghost" className="text-amber-200" disabled={quarantineKeys.isPending} onClick={() => { if (confirmAction("Quarantine every active API key for this user immediately?")) quarantineKeys.mutate({ userId: selectedUserId }); }}>Quarantine</Button></div><div className="rounded-xl border border-white/7 bg-black/15 p-3"><p className="mb-2 text-xs font-semibold uppercase tracking-[.16em] text-zinc-500">Usage by model and status</p>{usageRows.length ? <div className="space-y-2">{usageRows.slice(0, 8).map(row => <div key={`${row.modelSlug}-${row.status}`} className="flex items-center justify-between gap-2 text-xs"><span className="font-mono text-zinc-300">{row.modelSlug}</span><span className={row.status === "success" ? "text-[#b5ff77]" : "text-rose-300"}>{row.status} · {row.requests} req · {row.avgLatencyMs}ms</span></div>)}</div> : <p className="text-sm text-zinc-600">No request usage recorded for this user.</p>}</div><div className="rounded-xl border border-white/7 bg-black/15 p-3"><p className="mb-2 text-xs font-semibold uppercase tracking-[.16em] text-zinc-500">Credit correction</p><form className="grid gap-2 sm:grid-cols-[.7fr_1fr_1fr_auto]" onSubmit={event => { event.preventDefault(); if (creditDelta && creditDescription.trim() && confirmAction(`${creditDelta > 0 ? "Grant" : "Reverse"} ${Math.abs(creditDelta)} credits for this user?`)) adjustCredit.mutate({ userId: selectedUserId, amount: creditDelta, bucket: creditBucket, description: creditDescription.trim() }); }}><Input type="number" value={creditDelta || ""} onChange={event => setCreditDelta(number(event.target.value))} placeholder="± credits" className="bg-black/25" /><select value={creditBucket} onChange={event => setCreditBucket(event.target.value as typeof creditBucket)} className="control-select"><option value="purchased">Purchased</option><option value="stipend">Stipend</option></select><Input value={creditDescription} onChange={event => setCreditDescription(event.target.value)} className="bg-black/25" /><Button size="sm" disabled={!creditDelta || !creditDescription.trim() || adjustCredit.isPending} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]">Apply</Button></form></div><div className="rounded-xl border border-white/7 bg-black/15 p-3"><p className="mb-2 text-xs font-semibold uppercase tracking-[.16em] text-zinc-500">Recent credit ledger</p>{ledgerRows.length ? <div className="space-y-2">{ledgerRows.map(row => <div key={String(row.id)} className="flex items-center justify-between gap-2 text-xs"><span className="text-zinc-400">{row.description}</span><span className={Number(row.amount) >= 0 ? "text-[#b5ff77]" : "text-amber-200"}>{row.amount} · {row.entryType}</span></div>)}</div> : <p className="text-sm text-zinc-600">No ledger entries for this user.</p>}</div></> : <Empty>Select a user to inspect sessions, usage, and credit history.</Empty>}</div></div></Panel>;
}

function AdminObservabilityExplorer() {
  const [modelSlug, setModelSlug] = useState("");
  const [status, setStatus] = useState<"success" | "error" | "">("");
  const [eventType, setEventType] = useState("");
  const [actorUserId, setActorUserId] = useState("");
  const [targetUserId, setTargetUserId] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const logs = trpc.admin.requestLogs.useQuery({ modelSlug: modelSlug || undefined, status: status || undefined, from: from || undefined, to: to || undefined, limit: 50 });
  const events = trpc.admin.auditEvents.useQuery({ userId: actorUserId ? Number(actorUserId) : undefined, targetUserId: targetUserId ? Number(targetUserId) : undefined, eventType: eventType || undefined, from: from || undefined, to: to || undefined, limit: 50 });
  const logRows = asArray<{ id: string; userId: number | null; modelSlug: string; status: string; latencyMs: number; errorCode: string | null; createdAt: string }>(logs.data);
  const eventRows = asArray<{ id: string; eventType: string; userId: number | null; metadata: unknown; createdAt: string }>(events.data);
  const exportRedacted = () => { const blob = new Blob([JSON.stringify({ requests: logRows, auditEvents: eventRows }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "kiwi-router-redacted-diagnostics.json"; anchor.click(); URL.revokeObjectURL(url); };
  return <Panel title="Gateway diagnostics & audit explorer" detail="Search-ready redacted request metadata and founder audit events. Raw credentials and request bodies never enter this view." action={<Button size="sm" variant="outline" onClick={exportRedacted}>Export redacted JSON</Button>}><div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-5"><Input value={modelSlug} onChange={event => setModelSlug(event.target.value)} placeholder="Model filter" className="bg-black/25" /><select value={status} onChange={event => setStatus(event.target.value as typeof status)} className="control-select"><option value="">All request status</option><option value="success">Success</option><option value="error">Error</option></select><Input value={eventType} onChange={event => setEventType(event.target.value)} placeholder="Audit event" className="bg-black/25" /><Input value={actorUserId} onChange={event => setActorUserId(event.target.value.replace(/\D/g, ""))} placeholder="Actor ID" className="bg-black/25" /><Input value={targetUserId} onChange={event => setTargetUserId(event.target.value.replace(/\D/g, ""))} placeholder="Target ID" className="bg-black/25" /><Input type="date" value={from} onChange={event => setFrom(event.target.value)} className="bg-black/25" /><Input type="date" value={to} onChange={event => setTo(event.target.value)} className="bg-black/25" /></div><div className="grid gap-4 xl:grid-cols-2"><div><div className="mb-2 flex items-center justify-between"><p className="text-xs font-semibold uppercase tracking-[.16em] text-zinc-500">Recent requests</p><span className="text-xs text-zinc-600">{logRows.length} loaded</span></div>{logRows.length ? <div className="space-y-2">{logRows.slice(0, 12).map(row => <div key={String(row.id)} className="rounded-xl border border-white/7 bg-black/15 p-3 text-xs"><div className="flex justify-between gap-2"><span className="font-mono text-zinc-300">{row.modelSlug}</span><span className={row.status === "success" ? "text-[#b5ff77]" : "text-rose-300"}>{row.status}</span></div><p className="mt-1 text-zinc-600">{row.latencyMs}ms · user {row.userId ?? "—"} · {row.errorCode ?? "no error"}</p></div>)}</div> : <Empty>No gateway requests recorded.</Empty>}</div><div><div className="mb-2 flex items-center justify-between"><p className="text-xs font-semibold uppercase tracking-[.16em] text-zinc-500">Founder audit events</p><span className="text-xs text-zinc-600">{eventRows.length} loaded</span></div>{eventRows.length ? <div className="space-y-2">{eventRows.slice(0, 12).map(row => <div key={String(row.id)} className="rounded-xl border border-white/7 bg-black/15 p-3 text-xs"><div className="flex justify-between gap-2"><span className="text-zinc-300">{row.eventType}</span><span className="text-zinc-600">actor {row.userId ?? "system"}</span></div><pre className="mt-1 max-h-12 overflow-hidden whitespace-pre-wrap text-[10px] text-zinc-600">{JSON.stringify(row.metadata ?? {})}</pre></div>)}</div> : <Empty>No audit events recorded.</Empty>}</div></div></Panel>;
}

function RatePolicyPanel() {
  const [scope, setScope] = useState<"user" | "ip" | "api_key" | "provider" | "model">("user");
  const [subject, setSubject] = useState("");
  const [requestsPerMinute, setRequestsPerMinute] = useState(30);
  const [tokensPerMinute, setTokensPerMinute] = useState(10000);
  const policies = trpc.admin.rateLimitPolicies.useQuery();
  const save = trpc.admin.saveRateLimitPolicy.useMutation({ onSuccess: () => { void policies.refetch(); setSubject(""); toast.success("Rate-limit policy saved"); }, onError: error => toast.error(error.message) });
  const toggle = trpc.admin.setRateLimitPolicyEnabled.useMutation({ onSuccess: () => void policies.refetch(), onError: error => toast.error(error.message) });
  const rows = asArray<{ id: number; scope: string; subject: string; requestsPerMinute: number; tokensPerMinute: number; isEnabled: boolean }>(policies.data);
  return <Panel title="Scoped rate-limit policy presets" detail="Apply bounded request and token budgets by user, IP, API key, provider, or model. Every policy mutation is audited."><form className="grid gap-2 md:grid-cols-[.8fr_1.2fr_110px_120px_auto]" onSubmit={event => { event.preventDefault(); if (subject.trim()) save.mutate({ scope, subject: subject.trim(), requestsPerMinute, tokensPerMinute, isEnabled: true }); }}><select value={scope} onChange={event => setScope(event.target.value as typeof scope)} className="control-select"><option value="user">User</option><option value="ip">IP</option><option value="api_key">API key</option><option value="provider">Provider</option><option value="model">Model</option></select><Input value={subject} onChange={event => setSubject(event.target.value)} placeholder="Scope subject" className="bg-black/25" /><Input type="number" min={1} value={requestsPerMinute} onChange={event => setRequestsPerMinute(number(event.target.value))} className="bg-black/25" /><Input type="number" min={100} value={tokensPerMinute} onChange={event => setTokensPerMinute(number(event.target.value))} className="bg-black/25" /><Button disabled={!subject.trim() || save.isPending} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]">Save preset</Button></form><div className="mt-4 grid gap-2 md:grid-cols-2">{rows.length ? rows.map(row => <div key={row.id} className="flex items-center justify-between gap-3 rounded-xl border border-white/7 bg-black/15 p-3"><div><p className="text-sm text-zinc-200">{row.scope} · <span className="font-mono">{row.subject}</span></p><p className="mt-1 text-xs text-zinc-600">{row.requestsPerMinute} req/min · {row.tokensPerMinute} tokens/min</p></div><Button size="sm" variant="ghost" onClick={() => toggle.mutate({ id: row.id, isEnabled: !row.isEnabled })}>{row.isEnabled ? "Disable" : "Enable"}</Button></div>) : <Empty>No scoped policies configured.</Empty>}</div></Panel>;
}

function AdminOpsHealthCards({ providers, models, credits }: { providers: Provider[]; models: ModelRow[]; credits: unknown }) {
  const events = trpc.admin.auditEvents.useQuery({ limit: 20 });
  const healthy = providers.filter(provider => provider.isHealthy).length;
  const enabledRoutes = models.filter(row => row.model.isEnabled).length;
  const configuredRoutes = models.filter(row => row.provider).length;
  const eventRows = asArray(events.data);
  return <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Panel title="Provider uptime"><p className="text-2xl font-semibold text-zinc-100">{providers.length ? Math.round(healthy / providers.length * 100) : 0}%</p><p className="mt-1 text-xs text-zinc-500">{healthy}/{providers.length} healthy</p></Panel><Panel title="Route coverage"><p className="text-2xl font-semibold text-zinc-100">{configuredRoutes}</p><p className="mt-1 text-xs text-zinc-500">catalogued routes</p></Panel><Panel title="Model health"><p className="text-2xl font-semibold text-[#b5ff77]">{enabledRoutes}</p><p className="mt-1 text-xs text-zinc-500">enabled routes</p></Panel><Panel title="Credits"><p className="text-2xl font-semibold text-zinc-100">{compact((credits as { circulating?: unknown } | undefined)?.circulating)}</p><p className="mt-1 text-xs text-zinc-500">in circulation</p></Panel><Panel title="Security events"><p className="text-2xl font-semibold text-zinc-100">{eventRows.length}</p><p className="mt-1 text-xs text-zinc-500">latest loaded</p></Panel></div>;
}

function ProviderOperations({ providers }: { providers: Provider[] }) {
  const utils = trpc.useUtils();
  const [providerId, setProviderId] = useState(() => providers[0]?.id ?? 0);
  const [credentialName, setCredentialName] = useState("");
  const [credentialKey, setCredentialKey] = useState("");
  const selectedId = providerId || providers[0]?.id || 0;
  const credentials = trpc.admin.providerCredentials.useQuery({ providerId: selectedId }, { enabled: selectedId > 0 });
  const health = trpc.admin.providerHealth.useQuery({ providerId: selectedId }, { enabled: selectedId > 0 });
  const apiKeys = trpc.admin.apiKeys.useQuery({ providerId: selectedId }, { enabled: selectedId > 0 });
  const saveCredential = trpc.admin.saveProviderCredential.useMutation({ onSuccess: () => { setCredentialName(""); setCredentialKey(""); void credentials.refetch(); toast.success("Provider credential profile saved"); }, onError: error => toast.error(error.message) });
  const testCredential = trpc.admin.testProviderCredential.useMutation({ onSuccess: result => { void credentials.refetch(); void health.refetch(); result.ok ? toast.success(`Credential healthy · ${result.latencyMs} ms`) : toast.error(result.detail); }, onError: error => toast.error(error.message) });
  const setCredentialActive = trpc.admin.setProviderCredentialActive.useMutation({ onSuccess: () => { void credentials.refetch(); toast.success("Credential state updated"); }, onError: error => toast.error(error.message) });
  const setAccess = trpc.admin.setApiKeyProviderAccess.useMutation({ onSuccess: () => { void apiKeys.refetch(); toast.success("Provider access updated"); }, onError: error => toast.error(error.message) });
  const credentialRows = asArray<{ id: number; name: string; keyHint: string; isActive: boolean; lastTestOk: boolean | null; lastTestLatencyMs: number | null; lastSuccessAt: string | null }>(credentials.data);
  const healthRows = asArray<{ id: number; ok: boolean; statusCode: number | null; latencyMs: number; detail: string; createdAt: string }>(health.data).slice(0, 8);
  const keyRows = asArray<{ id: string; userEmail: string; name: string; keyPrefix: string; lastFour: string; isActive: boolean; accessIsEnabled: boolean | null; lastUsedAt: string | null }>(apiKeys.data).slice(0, 8);
  return <div className="space-y-4"><Panel title="Credential profiles & provider controls" detail="Rotate credentials without exposing secrets. Each profile is encrypted, masked, independently testable, and can be paused without deleting history."><div className="grid gap-3 lg:grid-cols-[220px_1fr]"><select value={selectedId} onChange={event => setProviderId(Number(event.target.value))} className="control-select h-10"><option value={0}>Select provider</option>{providers.map(provider => <option key={provider.id} value={provider.id}>{provider.displayName}</option>)}</select><form className="grid gap-2 sm:grid-cols-[1fr_1.4fr_auto]" onSubmit={event => { event.preventDefault(); if (selectedId && credentialName.trim() && credentialKey.trim()) saveCredential.mutate({ providerId: selectedId, name: credentialName.trim(), apiKey: credentialKey.trim() }); }}><Input value={credentialName} onChange={event => setCredentialName(event.target.value)} placeholder="Profile name · production" className="bg-black/25" /><Input type="password" value={credentialKey} onChange={event => setCredentialKey(event.target.value)} placeholder="New upstream credential" className="bg-black/25" /><Button disabled={!selectedId || !credentialName.trim() || credentialKey.trim().length < 8 || saveCredential.isPending} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]"><KeyRound className="mr-2 size-4" />Add profile</Button></form></div><div className="mt-4 grid gap-3 xl:grid-cols-2"><div className="space-y-2">{credentialRows.length ? credentialRows.map(row => <div key={row.id} className="flex flex-col gap-3 rounded-xl border border-white/7 bg-black/15 p-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm text-zinc-100">{row.name}</p><p className="mt-1 font-mono text-xs text-zinc-600">{row.keyHint} · {row.lastTestOk === true ? `healthy · ${row.lastTestLatencyMs ?? 0} ms` : row.lastTestOk === false ? "last test failed" : "not tested"} · last success {row.lastSuccessAt ? new Date(row.lastSuccessAt).toLocaleString() : "never"}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => testCredential.mutate({ id: row.id })} disabled={testCredential.isPending}><TestTube2 className="mr-1.5 size-3.5" />Test</Button><Button size="sm" variant="ghost" onClick={() => setCredentialActive.mutate({ id: row.id, isActive: !row.isActive })}>{row.isActive ? "Pause" : "Activate"}</Button></div></div>) : <Empty>No credential profiles for this provider.</Empty>}</div><div className="rounded-xl border border-white/7 bg-black/15 p-3"><div className="mb-2 flex items-center justify-between"><p className="text-xs font-semibold uppercase tracking-[.16em] text-zinc-500">Health history</p><span className="text-xs text-zinc-600">last 8 checks</span></div>{healthRows.length ? <div className="space-y-2">{healthRows.map(row => <div key={row.id} className="flex items-center justify-between gap-3 text-xs"><span className={row.ok ? "text-[#b5ff77]" : "text-amber-200"}>{row.ok ? "Operational" : "Degraded"}</span><span className="text-zinc-500">{row.detail}</span><span className="font-mono text-zinc-600">{row.latencyMs}ms · {new Date(row.createdAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span></div>)}</div> : <p className="text-sm text-zinc-600">Run a credential test to create the first health record.</p>}</div></div></Panel><Panel title="Provider-scoped API-key inventory" detail="Review which user keys can call this provider. Keys remain masked and the raw secret is never returned to the founder console.">{keyRows.length ? <div className="space-y-2">{keyRows.map(row => <div key={row.id} className="flex flex-col gap-2 rounded-xl border border-white/7 bg-black/15 p-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm text-zinc-200">{row.userEmail}</p><p className="mt-1 font-mono text-xs text-zinc-600">{row.name} · {row.keyPrefix}…{row.lastFour} · last used {row.lastUsedAt ? new Date(row.lastUsedAt).toLocaleDateString() : "never"}</p></div><Button size="sm" variant="outline" onClick={() => setAccess.mutate({ apiKeyId: row.id, providerId: selectedId, isEnabled: row.accessIsEnabled !== false ? false : true })}>{row.accessIsEnabled === false ? "Restore access" : "Quarantine"}</Button></div>)}</div> : <Empty>No API keys are assigned to this provider yet.</Empty>}</Panel></div>;
}

const sectionCopy: Record<Section, { eyebrow: string; title: string; detail: string }> = {
  operations: { eyebrow: "Founder command center", title: "Operations", detail: "Live controls for the gateway, credits, and current platform state." },
  providers: { eyebrow: "Upstream connections", title: "Providers", detail: "Connect, edit, test, synchronize, disable, and safely retire encrypted provider connections." },
  models: { eyebrow: "Routing control", title: "Model registry", detail: "Create, edit, price, enable, disable, and safely retire OpenAI-compatible model routes." },
  access: { eyebrow: "Security administration", title: "Access & safety", detail: "Control gateway safety, rate limits, and account access without mixing privileged actions into the user workspace." },
  growth: { eyebrow: "Programs & communications", title: "Growth", detail: "Manage credits, coupons, referrals, and in-workspace announcements." },
};

export function FounderControlCenter({ initialSection = "operations" }: { initialSection?: Section }) {
  const utils = trpc.useUtils();
  const [section, setSection] = useState<Section>(initialSection);
  const [editingProvider, setEditingProvider] = useState<number | null>(null);
  const [providerSlug, setProviderSlug] = useState("");
  const [providerName, setProviderName] = useState("");
  const [providerUrl, setProviderUrl] = useState("");
  const [providerKey, setProviderKey] = useState("");
  const [providerEnabled, setProviderEnabled] = useState(true);
  const [providerProtocol, setProviderProtocol] = useState<"openai" | "anthropic" | "gemini">("openai");
  const [providerHeaders, setProviderHeaders] = useState("{}");
  const [providerOriginalEnabled, setProviderOriginalEnabled] = useState(true);
  const [editingModel, setEditingModel] = useState<Model | null>(null);
  const [editModelName, setEditModelName] = useState("");
  const [editUpstreamId, setEditUpstreamId] = useState("");
  const [editProtocol, setEditProtocol] = useState<"openai" | "anthropic" | "gemini">("openai");
  const [editPriority, setEditPriority] = useState(100);
  const [editFallbackProviderId, setEditFallbackProviderId] = useState(0);
  const [editCapabilities, setEditCapabilities] = useState({ streaming: true, vision: false, tools: false, jsonMode: false, reasoning: false });
  const [sampleModelId, setSampleModelId] = useState(0);
  const [samplePrompt, setSamplePrompt] = useState("Reply with one concise sentence confirming this route is reachable.");
  const [newModelName, setNewModelName] = useState("");
  const [newModelSlug, setNewModelSlug] = useState("");
  const [newUpstreamId, setNewUpstreamId] = useState("");
  const [newProviderId, setNewProviderId] = useState("");
  const [newContextWindow, setNewContextWindow] = useState(128000);
  const [newInputPrice, setNewInputPrice] = useState("0");
  const [newOutputPrice, setNewOutputPrice] = useState("0");
  const [newCreditCost, setNewCreditCost] = useState("1");
  const [newProtocol, setNewProtocol] = useState<"openai" | "anthropic" | "gemini">("openai");
  const [newPriority, setNewPriority] = useState(100);
  const [newFallbackProviderId, setNewFallbackProviderId] = useState(0);
  const [newCapabilities, setNewCapabilities] = useState({ streaming: true, vision: false, tools: false, jsonMode: false, reasoning: false });
  const [mintEmail, setMintEmail] = useState("");
  const [mintAmount, setMintAmount] = useState(50);
  const [couponCode, setCouponCode] = useState("");
  const [couponCredits, setCouponCredits] = useState(25);
  const [couponUses, setCouponUses] = useState(100);
  const [announcement, setAnnouncement] = useState("");
  const [rpm, setRpm] = useState(30);
  const [tpm, setTpm] = useState(10000);

  const economy = trpc.admin.economy.useQuery();
  const users = trpc.admin.users.useQuery();
  const providersQuery = trpc.admin.providers.useQuery();
  const modelsQuery = trpc.admin.models.useQuery();
  const limits = trpc.admin.rateLimits.useQuery();
  const coupons = trpc.admin.coupons.useQuery();
  const announcements = trpc.admin.announcements.useQuery();
  const referrals = trpc.admin.referralMetrics.useQuery();
  const providers = asArray<Provider>(providersQuery.data);
  const models = asArray<ModelRow>(modelsQuery.data);
  const userRows = asArray<{ id: number; name: string; email: string; role: string; isDisabled: boolean }>(users.data);
  const couponRows = asArray<{ id: number; code: string; creditsAmount: string; usesCount: number; maxUses: number | null; isActive: boolean }>(coupons.data);
  const announcementRows = asArray<{ id: number; message: string; isActive: boolean }>(announcements.data);
  const selectedProviderExists = providers.some(provider => provider.id === Number(newProviderId));
  const activeProviders = useMemo(() => providers.filter(provider => provider.isEnabled), [providers]);

  const refreshAll = () => { void utils.admin.invalidate(); void utils.models.list.invalidate(); };
  const saveProvider = trpc.admin.saveProvider.useMutation({ onSuccess: () => { toast.success(editingProvider ? "Provider saved" : "Provider connected"); clearProviderForm(); void utils.admin.providers.invalidate(); }, onError: error => toast.error(error.message) });
  const testProvider = trpc.admin.testProviderConnection.useMutation({ onSuccess: result => { void utils.admin.providers.invalidate(); result.ok ? toast.success(`Connection healthy · ${result.latencyMs} ms`) : toast.error(result.detail); }, onError: error => toast.error(error.message) });
  const previewProvider = trpc.admin.previewProviderModels.useQuery({ providerId: 0 }, { enabled: false });
  const syncProvider = trpc.admin.syncProviderModels.useMutation({ onSuccess: result => { void utils.admin.models.invalidate(); if (!result.ok) { toast.error(result.detail); return; } toast.success(result.mode === "manual" ? "Manual route mapping required" : `${result.discovered} model routes discovered`); }, onError: error => toast.error(error.message) });
  const archiveProvider = trpc.admin.archiveProvider.useMutation({ onSuccess: () => { void utils.admin.providers.invalidate(); void utils.admin.models.invalidate(); toast.success("Provider and its routes were safely retired"); }, onError: error => toast.error(error.message) });
  const createModel = trpc.admin.createModel.useMutation({ onSuccess: () => { setNewModelName(""); setNewModelSlug(""); setNewUpstreamId(""); void utils.admin.models.invalidate(); void utils.models.list.invalidate(); toast.success("Model route created"); }, onError: error => toast.error(error.message) });
  const updateModel = trpc.admin.updateModel.useMutation({ onSuccess: () => { void utils.admin.models.invalidate(); void utils.models.list.invalidate(); toast.success("Model route updated"); }, onError: error => toast.error(error.message) });
  const testModelRoute = trpc.admin.testModelRoute.useMutation({ onSuccess: result => toast[result.ok ? "success" : "error"](`Model handshake: ${result.detail}`), onError: error => toast.error(error.message) });
  const testModelSample = trpc.admin.testModelSample.useMutation({ onSuccess: result => { toast[result.ok ? "success" : "error"](result.detail); if (result.preview) setSamplePrompt(result.preview); }, onError: error => toast.error(error.message) });
  const archiveModel = trpc.admin.archiveModel.useMutation({ onSuccess: () => { setEditingModel(null); void utils.admin.models.invalidate(); void utils.models.list.invalidate(); toast.success("Model route safely retired"); }, onError: error => toast.error(error.message) });
  const bulkModelLifecycle = trpc.admin.bulkModelLifecycle.useMutation({ onSuccess: result => { void utils.admin.models.invalidate(); void utils.models.list.invalidate(); toast.success(`${result.count} routes ${result.action}d`); }, onError: error => toast.error(error.message) });
  const saveRateLimits = trpc.admin.saveRateLimits.useMutation({ onSuccess: () => { void utils.admin.rateLimits.invalidate(); toast.success("Rate limits saved"); }, onError: error => toast.error(error.message) });
  const gatewaySwitch = trpc.admin.setGlobalApiEnabled.useMutation({ onSuccess: () => { void utils.admin.rateLimits.invalidate(); toast.success("Gateway safety state updated"); }, onError: error => toast.error(error.message) });
  const setUserDisabled = trpc.admin.setUserDisabled.useMutation({ onSuccess: () => { void utils.admin.users.invalidate(); toast.success("User access updated"); }, onError: error => toast.error(error.message) });
  const banUser = trpc.admin.banUser.useMutation({ onSuccess: () => { void utils.admin.users.invalidate(); toast.success("User, keys, and known access points were banned"); }, onError: error => toast.error(error.message) });
  const mint = trpc.admin.mintCredits.useMutation({ onSuccess: () => { setMintEmail(""); void utils.admin.economy.invalidate(); toast.success("Kiwi Credits granted"); }, onError: error => toast.error(error.message) });
  const createCoupon = trpc.admin.createCoupon.useMutation({ onSuccess: () => { setCouponCode(""); void utils.admin.coupons.invalidate(); toast.success("Coupon created"); }, onError: error => toast.error(error.message) });
  const deactivateCoupon = trpc.admin.deactivateCoupon.useMutation({ onSuccess: () => { void utils.admin.coupons.invalidate(); toast.success("Coupon deactivated"); }, onError: error => toast.error(error.message) });
  const createAnnouncement = trpc.admin.createAnnouncement.useMutation({ onSuccess: () => { setAnnouncement(""); void utils.admin.announcements.invalidate(); toast.success("Announcement published"); }, onError: error => toast.error(error.message) });
  const setAnnouncementActive = trpc.admin.setAnnouncementActive.useMutation({ onSuccess: () => { void utils.admin.announcements.invalidate(); toast.success("Announcement state updated"); }, onError: error => toast.error(error.message) });

  function clearProviderForm() { setEditingProvider(null); setProviderSlug(""); setProviderName(""); setProviderUrl(""); setProviderKey(""); setProviderEnabled(true); setProviderOriginalEnabled(true); }
  function beginProviderEdit(provider: Provider) { setEditingProvider(provider.id); setProviderSlug(provider.slug); setProviderName(provider.displayName); setProviderUrl(provider.baseUrl); setProviderKey(""); setProviderEnabled(provider.isEnabled); setProviderOriginalEnabled(provider.isEnabled); }
  function beginModelEdit(model: Model) { const config = model.routingConfig ?? {}; setEditingModel(model); setEditModelName(model.displayName); setEditUpstreamId(model.upstreamId); setEditProtocol((config.protocol as typeof editProtocol) ?? "openai"); setEditPriority(config.priority ?? 100); setEditFallbackProviderId(config.fallbackProviderId ?? 0); setEditCapabilities({ streaming: config.capabilities?.streaming ?? true, vision: config.capabilities?.vision ?? false, tools: config.capabilities?.tools ?? false, jsonMode: config.capabilities?.jsonMode ?? false, reasoning: config.capabilities?.reasoning ?? false }); }
  function saveEditedModel() { if (!editingModel || !editModelName.trim() || !editUpstreamId.trim()) return; const materialChange = editUpstreamId.trim() !== editingModel.upstreamId; if (!materialChange || confirmAction("Change this route's upstream model ID? Existing requests remain recorded against the previous route configuration.")) updateModel.mutate({ id: editingModel.id, displayName: editModelName.trim(), upstreamId: editUpstreamId.trim(), routingConfig: { protocol: editProtocol, priority: editPriority, fallbackProviderId: editFallbackProviderId || undefined, capabilities: editCapabilities } }); }
  const copy = (value: string) => navigator.clipboard.writeText(value).then(() => toast.success("Copied to clipboard")).catch(() => toast.error("Copy was unavailable"));
  const current = sectionCopy[section];

  return <div className="space-y-6"><header className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><p className="text-[11px] font-semibold uppercase tracking-[.18em] text-[#8ee53f]">{current.eyebrow}</p><h1 className="mt-2 text-2xl font-semibold text-zinc-100">{current.title}</h1><p className="mt-2 max-w-3xl text-sm text-zinc-500">{current.detail}</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={refreshAll} className="border-white/10 bg-white/[.03]"><RefreshCw className="mr-2 size-4" />Refresh data</Button><a href="/status" className="inline-flex items-center rounded-md border border-[#8ee53f]/25 bg-[#8ee53f]/[.05] px-3 text-sm font-medium text-[#b5ff77]"><Activity className="mr-2 size-4" />Live status</a></div></header><nav className="flex gap-2 overflow-x-auto border-b border-white/8 pb-3" aria-label="Founder console sections">{([{ id: "operations", label: "Operations", icon: Activity }, { id: "providers", label: "Providers", icon: CloudCog }, { id: "models", label: "Model registry", icon: Boxes }, { id: "access", label: "Access & safety", icon: ShieldCheck }, { id: "growth", label: "Growth", icon: Sparkles }] as const).map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => setSection(item.id)} className={`inline-flex shrink-0 items-center gap-2 rounded-xl px-3 py-2 text-sm transition ${section === item.id ? "bg-[#8ee53f] text-black" : "bg-white/[.03] text-zinc-400 hover:bg-white/[.07] hover:text-zinc-100"}`}><Icon className="size-4" />{item.label}</button>; })}</nav>

    {section === "operations" && <div className="space-y-4"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Panel title="Gateway state"><div className="flex items-center justify-between"><span className={`inline-flex items-center gap-2 text-sm ${limits.data?.globalApiEnabled ? "text-[#b5ff77]" : "text-amber-200"}`}>{limits.data?.globalApiEnabled ? <CheckCircle2 className="size-4" /> : <PauseCircle className="size-4" />}{limits.data?.globalApiEnabled ? "Routing enabled" : "Routing paused"}</span><Switch checked={Boolean(limits.data?.globalApiEnabled)} onCheckedChange={enabled => { if (enabled || confirmAction("Pause all gateway requests?")) gatewaySwitch.mutate({ enabled }); }} /></div></Panel><Panel title="Configured providers"><p className="text-3xl font-semibold text-zinc-100">{activeProviders.length}</p><p className="mt-1 text-xs text-zinc-500">{providers.filter(provider => provider.isHealthy).length} recently healthy</p></Panel><Panel title="Credits in circulation"><p className="text-3xl font-semibold text-zinc-100">{compact(economy.data?.circulating)}</p><p className="mt-1 text-xs text-zinc-500">Across {compact(economy.data?.users)} accounts</p></Panel><Panel title="24h credit burn"><p className="text-3xl font-semibold text-zinc-100">{compact(economy.data?.dailyBurn)}</p><p className="mt-1 text-xs text-zinc-500">Settled upstream usage</p></Panel></div><div className="grid gap-4 xl:grid-cols-[1.1fr_.9fr]"><Panel title="Founder safety checklist" detail="Provider credentials remain encrypted server-side. Management actions are audited."><div className="space-y-2">{[["Provider tests", "Non-billable catalog handshake"], ["Model routing", "Create, edit, price, enable, disable, or retire"], ["User security", "Disable access or propagate a ban"], ["Revenue controls", "Credits, coupons, referrals, and announcements"]].map(([title, detail]) => <div key={title} className="flex gap-3 rounded-xl border border-white/7 bg-black/15 p-3"><ShieldCheck className="mt-0.5 size-4 text-[#a5f763]" /><div><p className="text-sm text-zinc-200">{title}</p><p className="text-xs text-zinc-500">{detail}</p></div></div>)}</div></Panel><Panel title="Quick actions"><div className="grid gap-2 sm:grid-cols-2"><Button onClick={() => setSection("providers")} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]"><Link2 className="mr-2 size-4" />Connect provider</Button><Button variant="outline" onClick={() => setSection("models")} className="border-white/10"><Plus className="mr-2 size-4" />Add route</Button><Button variant="outline" onClick={() => setSection("access")} className="border-white/10"><Users className="mr-2 size-4" />Manage users</Button><Button variant="outline" onClick={() => setSection("growth")} className="border-white/10"><Ticket className="mr-2 size-4" />Create coupon</Button></div></Panel></div></div>}

    {section === "operations" && <AdminOpsHealthCards providers={providers} models={models} credits={economy.data} />}

    {section === "operations" && <RatePolicyPanel />}

    {section === "providers" && <div className="grid gap-4 xl:grid-cols-[.85fr_1.15fr]"><Panel title={editingProvider ? "Edit provider connection" : "Connect a provider"} detail="A blank API-key field preserves an existing encrypted credential during edits." action={editingProvider ? <Button size="sm" variant="ghost" onClick={clearProviderForm}><X className="mr-1 size-4" />Cancel</Button> : undefined}><form className="space-y-3" onSubmit={event => { event.preventDefault(); if (!providerSlug.trim() || !providerName.trim() || !/^https:\/\//.test(providerUrl)) return; if (editingProvider && providerEnabled !== providerOriginalEnabled && !confirmAction(`${providerEnabled ? "Enable" : "Disable"} ${providerName} for gateway routing?`)) return; saveProvider.mutate({ slug: providerSlug.trim().toLowerCase(), displayName: providerName.trim(), baseUrl: providerUrl.trim(), protocol: providerProtocol, requestHeaders: (() => { try { const parsed = JSON.parse(providerHeaders); return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {}; } catch { return {}; } })(), apiKey: providerKey.trim() || undefined, isEnabled: providerEnabled }); }}><div className="grid gap-3 sm:grid-cols-2"><Input value={providerName} onChange={event => setProviderName(event.target.value)} placeholder="Provider name" className="bg-black/25" /><Input value={providerSlug} onChange={event => setProviderSlug(event.target.value.toLowerCase().replace(/[^a-z0-9_-]/g, ""))} placeholder="provider-slug" className="bg-black/25 font-mono" /></div><Input value={providerUrl} onChange={event => setProviderUrl(event.target.value)} placeholder="https://api.provider.com/v1" className="bg-black/25 font-mono" /><div className="grid gap-3 sm:grid-cols-2"><select value={providerProtocol} onChange={event => setProviderProtocol(event.target.value as typeof providerProtocol)} className="control-select"><option value="openai">OpenAI-compatible</option><option value="anthropic">Anthropic</option><option value="gemini">Gemini</option></select><Input value={providerHeaders} onChange={event => setProviderHeaders(event.target.value)} placeholder='Static headers JSON, e.g. {"anthropic-version":"2023-06-01"}' className="bg-black/25 font-mono" /></div><Input type="password" value={providerKey} onChange={event => setProviderKey(event.target.value)} placeholder={editingProvider ? "Leave blank to preserve encrypted key" : "Upstream API key"} className="bg-black/25" /><label className="flex items-center justify-between rounded-xl border border-white/7 bg-black/15 p-3 text-sm text-zinc-300"><span>Enable this provider for routing</span><Switch checked={providerEnabled} onCheckedChange={setProviderEnabled} /></label><Button className="w-full bg-[#8ee53f] text-black hover:bg-[#a5f763]" disabled={saveProvider.isPending || !providerSlug.trim() || !providerName.trim() || !/^https:\/\//.test(providerUrl)}>{saveProvider.isPending ? <Loader2 className="size-4 animate-spin" /> : <Save className="size-4" />}{editingProvider ? "Save connection" : "Create connection"}</Button></form></Panel><Panel title="Provider inventory" detail="Test checks the catalog endpoint only; it never sends a model completion request.">{providers.length ? <div className="space-y-3">{providers.map(provider => <div key={provider.id} className="rounded-xl border border-white/7 bg-black/15 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-medium text-zinc-100">{provider.displayName}</p><p className="mt-1 font-mono text-xs text-zinc-600">{provider.slug} · {provider.isConfigured ? "credential encrypted" : "no credential"}</p></div><div className="flex gap-2"><span className={`rounded-full px-2 py-1 text-[10px] font-semibold uppercase ${provider.isHealthy ? "bg-[#8ee53f]/10 text-[#b5ff77]" : "bg-amber-300/10 text-amber-200"}`}>{provider.isHealthy ? "healthy" : "unverified"}</span><span className="rounded-full bg-white/[.06] px-2 py-1 text-[10px] font-semibold uppercase text-zinc-400">{provider.isEnabled ? "enabled" : "retired"}</span></div></div><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" variant="outline" disabled={!provider.isConfigured || testProvider.isPending} onClick={() => testProvider.mutate({ providerId: provider.id })}><TestTube2 className="mr-1.5 size-3.5" />Test</Button><Button size="sm" variant="outline" disabled={!provider.isConfigured || previewProvider.isFetching} onClick={async () => { const result = await utils.admin.previewProviderModels.fetch({ providerId: provider.id }); if (!result.ok) { toast.error(result.detail); return; } toast.success(result.mode === "manual" ? result.detail : `${result.models.length} catalog entries · ${result.models.filter(item => !item.alreadyExists).length} new`); }}><Eye className="mr-1.5 size-3.5" />Preview models</Button><Button size="sm" variant="outline" disabled={!provider.isConfigured || syncProvider.isPending} onClick={() => syncProvider.mutate({ providerId: provider.id })}><RefreshCw className="mr-1.5 size-3.5" />Sync models</Button><Button size="sm" variant="ghost" onClick={() => beginProviderEdit(provider)}>Edit</Button>{provider.isEnabled && <Button size="sm" variant="ghost" className="text-amber-200" onClick={() => { if (confirmAction(`Safely retire ${provider.displayName} and disable attached routes? Historic usage remains intact.`)) archiveProvider.mutate({ providerId: provider.id }); }}><Archive className="mr-1.5 size-3.5" />Retire</Button>}</div></div>)}</div> : <Empty>Connect a provider to begin model discovery and routing.</Empty>}</Panel></div>}

    {section === "providers" && <div className="space-y-4"><MiniOmniRouteWizard /><ProviderOperations providers={providers} /></div>}

    {section === "access" && <AdminUserIntelligence />}

    {section === "access" && <AdminObservabilityExplorer />}

    {section === "models" && <div className="space-y-4"><ModelIdentityRegistry /><KiwiAutoPolicyPanel /><Panel title="Provider/model test playground" detail="Run a bounded founder sample without deducting Kiwi Credits or writing normal user usage. Provider charges may still apply upstream."><div className="grid gap-3 md:grid-cols-[1fr_2fr_auto]"><select value={sampleModelId} onChange={event => setSampleModelId(Number(event.target.value))} className="control-select"><option value={0}>Select a model route</option>{models.map(({ model, provider }) => <option key={model.id} value={model.id}>{provider.displayName} · {model.displayName}</option>)}</select><Textarea value={samplePrompt} onChange={event => setSamplePrompt(event.target.value)} maxLength={2000} className="min-h-10 bg-black/25" placeholder="Sample prompt" /><Button disabled={!sampleModelId || !samplePrompt.trim() || testModelSample.isPending} onClick={() => testModelSample.mutate({ modelId: sampleModelId, prompt: samplePrompt.trim() })} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]">Run sample</Button></div><p className="mt-2 text-xs text-zinc-600">The result is capped to a short preview and the action is audited as a founder test, not a customer request.</p></Panel>{editingModel && <Panel title="Edit selected route" detail="Changing the upstream ID is a material routing change and requires confirmation. The route slug is immutable so historic usage remains coherent." action={<Button size="sm" variant="ghost" onClick={() => setEditingModel(null)}><X className="mr-1 size-4" />Close</Button>}><div className="grid gap-3 md:grid-cols-[1fr_1fr_auto]"><Input value={editModelName} onChange={event => setEditModelName(event.target.value)} placeholder="Display name" className="bg-black/25" /><Input value={editUpstreamId} onChange={event => setEditUpstreamId(event.target.value)} placeholder="Upstream model ID" className="bg-black/25" /><select value={editProtocol} onChange={event => setEditProtocol(event.target.value as typeof editProtocol)} className="control-select"><option value="openai">OpenAI-compatible</option><option value="anthropic">Anthropic</option><option value="gemini">Gemini</option></select><Input type="number" min={1} max={1000} value={editPriority} onChange={event => setEditPriority(number(event.target.value))} placeholder="Priority" className="bg-black/25" /><select value={editFallbackProviderId} onChange={event => setEditFallbackProviderId(Number(event.target.value))} className="control-select"><option value={0}>No fallback</option>{activeProviders.map(provider => <option key={provider.id} value={provider.id}>{provider.displayName} fallback</option>)}</select><div className="flex flex-wrap items-center gap-2 rounded-lg border border-white/7 bg-black/15 px-2 py-1 text-[11px] text-zinc-400 md:col-span-2">{(Object.keys(editCapabilities) as Array<keyof typeof editCapabilities>).map(capability => <label key={capability} className="inline-flex items-center gap-1"><input type="checkbox" checked={editCapabilities[capability]} onChange={event => setEditCapabilities(previous => ({ ...previous, [capability]: event.target.checked }))} />{capability}</label>)}</div><Button disabled={!editModelName.trim() || !editUpstreamId.trim() || updateModel.isPending} onClick={saveEditedModel} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]"><Save className="mr-2 size-4" />Save route</Button></div><code className="mt-3 block text-xs text-zinc-600">{editingModel.slug}</code></Panel>}<Panel title="Add a manual route" detail="Use reviewed model IDs for providers that do not expose a compatible catalog."><form className="grid gap-3 md:grid-cols-2 xl:grid-cols-8" onSubmit={event => { event.preventDefault(); if (newModelName.trim() && newModelSlug.trim() && newUpstreamId.trim() && selectedProviderExists) createModel.mutate({ displayName: newModelName.trim(), slug: newModelSlug.trim(), upstreamId: newUpstreamId.trim(), providerId: Number(newProviderId), contextWindow: newContextWindow, inputPrice: newInputPrice, outputPrice: newOutputPrice, creditCostPer1kTokens: newCreditCost, isEnabled: false, routingConfig: { protocol: newProtocol, priority: newPriority, fallbackProviderId: newFallbackProviderId || undefined, capabilities: newCapabilities } }); }}><Input value={newModelName} onChange={event => setNewModelName(event.target.value)} placeholder="Display name" className="bg-black/25" /><Input value={newModelSlug} onChange={event => setNewModelSlug(event.target.value)} placeholder="kiwi/provider-model" className="bg-black/25 font-mono" /><Input value={newUpstreamId} onChange={event => setNewUpstreamId(event.target.value)} placeholder="Upstream model ID" className="bg-black/25" /><select value={newProviderId} onChange={event => setNewProviderId(event.target.value)} className="control-select"><option value="">Select provider</option>{activeProviders.map(provider => <option key={provider.id} value={provider.id}>{provider.displayName}</option>)}</select><Input type="number" min={1} max={2000000} value={newContextWindow} onChange={event => setNewContextWindow(number(event.target.value))} placeholder="Context" className="bg-black/25" /><Input value={newInputPrice} onChange={event => setNewInputPrice(event.target.value)} placeholder="Input $/M" className="bg-black/25" /><Input value={newOutputPrice} onChange={event => setNewOutputPrice(event.target.value)} placeholder="Output $/M" className="bg-black/25" /><Input value={newCreditCost} onChange={event => setNewCreditCost(event.target.value)} placeholder="Credits/1k" className="bg-black/25" /><select value={newProtocol} onChange={event => setNewProtocol(event.target.value as typeof newProtocol)} className="control-select"><option value="openai">OpenAI-compatible</option><option value="anthropic">Anthropic</option><option value="gemini">Gemini-compatible</option></select><Input type="number" min={1} max={1000} value={newPriority} onChange={event => setNewPriority(number(event.target.value))} placeholder="Priority" className="bg-black/25" /><select value={newFallbackProviderId} onChange={event => setNewFallbackProviderId(Number(event.target.value))} className="control-select"><option value={0}>No fallback</option>{activeProviders.map(provider => <option key={provider.id} value={provider.id}>{provider.displayName} fallback</option>)}</select><div className="flex flex-wrap items-center gap-2 rounded-lg border border-white/7 bg-black/15 px-2 py-1 text-[11px] text-zinc-400 xl:col-span-2">{(Object.keys(newCapabilities) as Array<keyof typeof newCapabilities>).map(capability => <label key={capability} className="inline-flex items-center gap-1"><input type="checkbox" checked={newCapabilities[capability]} onChange={event => setNewCapabilities(previous => ({ ...previous, [capability]: event.target.checked }))} />{capability}</label>)}</div><Button disabled={!newModelName.trim() || !newModelSlug.trim() || !newUpstreamId.trim() || !selectedProviderExists || createModel.isPending} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]"><Plus className="mr-2 size-4" />Add route</Button></form></Panel><Panel title="Route inventory" detail="Routes can be enabled, disabled, priced, fully edited, or safely retired while historical usage and ledgers remain preserved." action={<div className="flex flex-wrap gap-1"><Button size="sm" variant="ghost" disabled={!models.length || bulkModelLifecycle.isPending} onClick={() => { if (confirmAction("Enable every route for gateway routing?")) bulkModelLifecycle.mutate({ ids: models.map(row => row.model.id), action: "enable" }); }}>Enable all</Button><Button size="sm" variant="ghost" disabled={!models.length || bulkModelLifecycle.isPending} onClick={() => { if (confirmAction("Disable every route for gateway routing?")) bulkModelLifecycle.mutate({ ids: models.map(row => row.model.id), action: "disable" }); }}>Disable all</Button><Button size="sm" variant="ghost" disabled={!models.length || bulkModelLifecycle.isPending} onClick={() => { if (confirmAction("Archive every route? This preserves usage history and disables routing.")) bulkModelLifecycle.mutate({ ids: models.map(row => row.model.id), action: "archive" }); }}>Archive all</Button><Button size="sm" variant="ghost" disabled={!models.length || bulkModelLifecycle.isPending} onClick={() => { if (confirmAction("Restore every archived route for routing? Review provider health before proceeding.")) bulkModelLifecycle.mutate({ ids: models.map(row => row.model.id), action: "restore" }); }}>Restore all</Button></div>}>{models.length ? <div className="space-y-2">{models.map(({ model, provider }) => <div key={model.id} className="grid items-center gap-3 rounded-xl border border-white/7 bg-black/15 p-3 lg:grid-cols-[1.4fr_.7fr_125px_110px_auto]"><div><p className="text-sm text-zinc-100">{model.displayName}</p><code className="mt-1 block text-xs text-zinc-600">{provider.displayName} · {model.slug}</code><p className="mt-1 text-[10px] uppercase tracking-wide text-zinc-600">{model.routingConfig?.protocol ?? "openai"} · priority {model.routingConfig?.priority ?? 100} · {Object.entries(model.routingConfig?.capabilities ?? {}).filter(([, enabled]) => enabled).map(([name]) => name).join(", ") || "no capability flags"}</p></div><p className="text-xs text-zinc-500">{compact(model.contextWindow)} context</p><Input defaultValue={model.creditCostPer1kTokens} className="h-9 bg-black/25" onBlur={event => { const value = event.target.value; if (/^\d+(\.\d{1,3})?$/.test(value) && value !== model.creditCostPer1kTokens) updateModel.mutate({ id: model.id, creditCostPer1kTokens: value }); }} /><label className="flex items-center justify-between gap-2 text-xs text-zinc-400"><span>{model.isEnabled ? "Live" : "Disabled"}</span><Switch checked={model.isEnabled} onCheckedChange={isEnabled => { if (confirmAction(`${isEnabled ? "Enable" : "Disable"} ${model.displayName} for gateway routing?`)) updateModel.mutate({ id: model.id, isEnabled }); }} /></label><div className="flex gap-1"><Button size="sm" variant="ghost" disabled={testModelRoute.isPending} onClick={() => testModelRoute.mutate({ modelId: model.id })}>Test</Button><Button size="sm" variant="ghost" onClick={() => beginModelEdit(model)}>Edit</Button><Button size="sm" variant="ghost" className="text-amber-200" onClick={() => { if (confirmAction(`Safely retire ${model.displayName}? It stops routing but preserves historic usage.`)) archiveModel.mutate({ id: model.id }); }}><Archive className="size-3.5" /></Button></div></div>)}</div> : <Empty>Create a route manually or synchronize a configured provider.</Empty>}</Panel></div>}

    {section === "access" && <div className="space-y-4"><div className="grid gap-4 xl:grid-cols-2"><Panel title="Gateway rate limits" detail="Applied before upstream routing."><div className="grid gap-3 sm:grid-cols-2"><Input type="number" value={rpm} onChange={event => setRpm(number(event.target.value))} placeholder="Requests/min" className="bg-black/25" /><Input type="number" value={tpm} onChange={event => setTpm(number(event.target.value))} placeholder="Tokens/min" className="bg-black/25" /></div><Button className="mt-3 w-full bg-[#8ee53f] text-black hover:bg-[#a5f763]" onClick={() => saveRateLimits.mutate({ requestsPerMinute: rpm, tokensPerMinute: tpm })}><SlidersHorizontal className="mr-2 size-4" />Save limits</Button></Panel><Panel title="Gateway safety switch" detail="Pausing blocks completions globally while preserving accounts and provider configuration."><div className="flex items-center justify-between rounded-xl border border-white/7 bg-black/15 p-4"><div><p className="font-medium text-zinc-100">{limits.data?.globalApiEnabled ? "Gateway is live" : "Gateway is paused"}</p><p className="mt-1 text-xs text-zinc-500">Use for incident response or provider maintenance.</p></div><Switch checked={Boolean(limits.data?.globalApiEnabled)} onCheckedChange={enabled => { if (enabled || confirmAction("Pause all gateway requests now?")) gatewaySwitch.mutate({ enabled }); }} /></div></Panel></div><Panel title="User security" detail="Disable access for recovery or ban an account to revoke keys and propagate account, domain, and recent-IP blocks.">{userRows.length ? <div className="space-y-2">{userRows.map(user => <div key={user.id} className="flex flex-col gap-3 rounded-xl border border-white/7 bg-black/15 p-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm text-zinc-100">{user.name}</p><p className="mt-1 text-xs text-zinc-500">{user.email} · {user.role} · {user.isDisabled ? "disabled" : "active"}</p></div>{user.role === "founder" ? <span className="text-xs text-zinc-600">Immutable founder</span> : <div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => setUserDisabled.mutate({ id: user.id, isDisabled: !user.isDisabled })}>{user.isDisabled ? <PlayCircle className="mr-1.5 size-3.5" /> : <PauseCircle className="mr-1.5 size-3.5" />}{user.isDisabled ? "Restore" : "Disable"}</Button><Button size="sm" variant="ghost" className="text-rose-300" onClick={() => { if (confirmAction(`Ban ${user.email} and revoke their API keys?`)) banUser.mutate({ id: user.id, reason: "Founder security action" }); }}><Ban className="mr-1.5 size-3.5" />Ban</Button></div>}</div>)}</div> : <Empty>No accounts are available.</Empty>}</Panel></div>}

    {section === "growth" && <div className="space-y-4"><div className="grid gap-4 xl:grid-cols-2"><Panel title="Grant Kiwi Credits" detail="Founder grants are permanent purchased credits with a ledger entry."><form className="flex flex-col gap-3 sm:flex-row" onSubmit={event => { event.preventDefault(); if (mintEmail.trim() && mintAmount > 0) mint.mutate({ email: mintEmail, amount: mintAmount, description: "Founder grant" }); }}><Input type="email" value={mintEmail} onChange={event => setMintEmail(event.target.value)} placeholder="user@example.com" className="bg-black/25" /><Input type="number" value={mintAmount} onChange={event => setMintAmount(number(event.target.value))} className="bg-black/25 sm:w-28" /><Button disabled={!mintEmail.trim() || mintAmount <= 0 || mint.isPending} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]"><CircleDollarSign className="mr-2 size-4" />Grant</Button></form></Panel><Panel title="Referral signal"><div className="grid grid-cols-3 gap-3"><div><p className="text-[10px] uppercase tracking-wider text-zinc-600">Total</p><p className="mt-1 text-xl font-semibold text-zinc-100">{compact(referrals.data?.total)}</p></div><div><p className="text-[10px] uppercase tracking-wider text-zinc-600">Activated</p><p className="mt-1 text-xl font-semibold text-zinc-100">{compact(referrals.data?.activated)}</p></div><div><p className="text-[10px] uppercase tracking-wider text-zinc-600">Claimed</p><p className="mt-1 text-xl font-semibold text-[#b5ff77]">{compact(referrals.data?.rewardsClaimed)}</p></div></div></Panel></div><div className="grid gap-4 xl:grid-cols-[1.1fr_.9fr]"><Panel title="Coupon program" detail="Redemption is limited by unique user and network hashes."><form className="grid gap-2 sm:grid-cols-3" onSubmit={event => { event.preventDefault(); if (couponCode.trim() && couponCredits > 0) createCoupon.mutate({ code: couponCode.trim().toUpperCase(), creditsAmount: couponCredits, maxUses: couponUses || undefined }); }}><Input value={couponCode} onChange={event => setCouponCode(event.target.value.toUpperCase())} placeholder="KIWI-LAUNCH" className="bg-black/25 font-mono uppercase" /><Input type="number" value={couponCredits} onChange={event => setCouponCredits(number(event.target.value))} className="bg-black/25" /><div className="flex gap-2"><Input type="number" value={couponUses} onChange={event => setCouponUses(number(event.target.value))} className="min-w-0 bg-black/25" /><Button disabled={!couponCode.trim() || couponCredits <= 0 || createCoupon.isPending} className="bg-[#8ee53f] text-black hover:bg-[#a5f763]"><Ticket className="size-4" /></Button></div></form><div className="mt-3 max-h-64 space-y-2 overflow-auto">{couponRows.length ? couponRows.map(coupon => <div key={coupon.id} className="flex items-center justify-between rounded-xl border border-white/7 bg-black/15 p-3"><div><code className="text-sm text-[#b5ff77]">{coupon.code}</code><p className="mt-1 text-xs text-zinc-500">{compact(coupon.creditsAmount)} credits · {coupon.usesCount}/{coupon.maxUses ?? "∞"} uses</p></div>{coupon.isActive ? <Button size="sm" variant="ghost" onClick={() => deactivateCoupon.mutate({ id: coupon.id })}>Deactivate</Button> : <span className="text-xs text-zinc-600">Inactive</span>}</div>) : <Empty>No coupons created yet.</Empty>}</div></Panel><Panel title="Announcements" detail="Publish an in-workspace notice and hide it without deleting its audit record."><form className="space-y-2" onSubmit={event => { event.preventDefault(); if (announcement.trim()) createAnnouncement.mutate({ message: announcement.trim(), kind: "notice", creditsPerUser: 0 }); }}><Textarea value={announcement} onChange={event => setAnnouncement(event.target.value)} placeholder="Maintenance window or product update" className="min-h-24 bg-black/25" /><Button disabled={!announcement.trim() || createAnnouncement.isPending} className="w-full bg-[#8ee53f] text-black hover:bg-[#a5f763]"><Megaphone className="mr-2 size-4" />Publish</Button></form><div className="mt-3 max-h-56 space-y-2 overflow-auto">{announcementRows.length ? announcementRows.map(item => <div key={item.id} className="flex items-start justify-between gap-3 rounded-xl border border-white/7 bg-black/15 p-3"><p className="text-sm text-zinc-300">{item.message}</p><Button size="sm" variant="ghost" onClick={() => setAnnouncementActive.mutate({ id: item.id, isActive: !item.isActive })}>{item.isActive ? "Hide" : "Show"}</Button></div>) : <Empty>No announcements created yet.</Empty>}</div></Panel></div></div>}
  </div>;
}
